// K-04: a flag raised, rather than a problem waiting to be noticed.
const cfg = $('Config').first().json;
const s = $json;
const flags = [];
const num = (v) => Number(v || 0);

if (num(s.failed_logins_1h) >= Number(cfg.failed_login_threshold)) {
  flags.push(`${s.failed_logins_1h} failed sign-ins in the last hour across `
    + `${s.failed_login_accounts} account(s). A run against several accounts is `
    + `password guessing, not somebody being forgetful.`);
}
if (num(s.deletions_24h) >= Number(cfg.deletion_threshold)) {
  flags.push(`${s.deletions_24h} delete actions in the audit trail in 24 hours `
    + `(out of ${s.audit_events_24h} events). Worth a look at who and why.`);
}
if (num(s.newly_overdue_7d) >= Number(cfg.overdue_threshold)) {
  flags.push(`${s.newly_overdue_7d} compliance items went overdue in the last 7 days `
    + `- ${s.overdue_now} are overdue in total. The backlog is growing, not clearing.`);
}
const prev = num(s.leads_prev_24h), now_ = num(s.leads_24h);
if (prev >= 5 && now_ <= Math.floor(prev / 2)) {
  flags.push(`Lead volume halved: ${now_} in the last 24h against ${prev} the day `
    + `before. Check the portal feeds and the ad accounts before assuming it is a quiet day.`);
}
if (num(s.leads_unassigned) >= Number(cfg.unassigned_threshold)) {
  flags.push(`${s.leads_unassigned} leads are sitting unassigned in New or Contacted.`);
}

if (!flags.length) return [];
return [{ json: {
  channel: 'email,slack',
  to_email: cfg.director_email,
  slack_channel: 'dharani-alerts',
  subject: `[DHARANI 360] ${flags.length} thing(s) worth looking at`,
  message: `Automatic check at ${new Date().toISOString().slice(0,16).replace('T',' ')} UTC found:\n\n`
    + flags.map((f, i) => `${i + 1}. ${f}`).join('\n\n')
    + `\n\nControl Tower: ${cfg.portal_url}\nAudit Trail: ${cfg.portal_url}/audit`,
}}];
